import React, { useState, useCallback, FormEvent } from 'react';
import { NavLink, useNavigate } from 'react-router-dom';
import { ROUTES } from '../../utils/constants';
import { EmailInput } from '@ya.praktikum/react-developer-burger-ui-components';
import { MainForm } from '../../components';
import passwordResetApi from '../../utils/api/PasswordResetApi';
import { IReqData } from '../../utils/api/types';
import style from './ForgotPassword.module.scss';

interface IForgotPasswordForm {
  email: string,
}

export default function ForgotPasswordPage() {
  const [formData, setFormData] = useState<IForgotPasswordForm | IReqData>({ email: '' });
  const navigate = useNavigate();

  const handleSetValue = useCallback(async (event: React.ChangeEvent<HTMLInputElement>) => {
    const { value, name } = event.target;

    setFormData((oldValues) => {
      const newValues = {
        ...oldValues,
        [name]: value,
      };

      return newValues;
    });
  }, []);

  const handleSubmit = useCallback(async (e: FormEvent) => {
    e.preventDefault();
    try {
      const data = await passwordResetApi.checkEmailRequest(formData as IReqData);
      if (data?.success) {
        navigate(ROUTES.RESET_PASSWORD);
      }
    } catch (error) {
      console.error(error);
    }
  }, [formData]);

  return (
    <div className={style.forgotPassword}>
      <MainForm
        formTitle="Восстановление пароля"
        submitText="Восстановить"
        onSubmit={handleSubmit}
      >
        <EmailInput
          placeholder={'Укажите e-mail'}
          onChange={handleSetValue}
          value={formData.email as string}
          name={'email'}
        />
      </MainForm>

      <div className={style.footer}>
        <div className={style.linkContainer}>
          <span className={style.linkText}>Вспомнили пароль?</span>
          <NavLink className={style.link} to={ROUTES.LOGIN}>Войти</NavLink>
        </div>
      </div>
    </div>
  );
}
